CREATE OR REPLACE FUNCTION public.admin_reject_renewal(p_session_token text, p_renewal_id uuid, p_admin_remarks text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _admin_id uuid;
  _renewal record;
  _owner_id uuid;
  _now timestamptz := clock_timestamp();
  _remarks text := trim(p_admin_remarks);
BEGIN
  SELECT vat.admin_id INTO _admin_id
  FROM public.validate_admin_session_token(p_session_token) vat
  LIMIT 1;

  IF _admin_id IS NULL THEN
    RAISE EXCEPTION 'Admin account is not authorized.';
  END IF;

  IF length(_remarks) < 10 THEN
    RAISE EXCEPTION 'Detailed rejection remarks of at least 10 characters are required.';
  END IF;

  SELECT * INTO _renewal
  FROM public.organization_renewals
  WHERE id = p_renewal_id
  FOR UPDATE;

  IF _renewal.id IS NULL THEN
    RAISE EXCEPTION 'Renewal application not found.';
  END IF;

  IF _renewal.status NOT IN ('submitted', 'under_review', 'resubmitted') THEN
    RAISE EXCEPTION 'Renewal can only be rejected from a reviewable status. Current status: "%".', _renewal.status;
  END IF;

  SELECT user_id INTO _owner_id
  FROM public.organization_profiles
  WHERE id = _renewal.organization_id;

  UPDATE public.organization_renewals
  SET
    status = 'rejected',
    admin_remarks = _remarks,
    reviewed_by = _admin_id,
    reviewed_at = _now,
    updated_at = _now
  WHERE id = p_renewal_id;

  UPDATE public.document_submissions
  SET
    status = 'rejected_red',
    reviewed_by = _admin_id,
    reviewed_at = _now,
    overall_remarks = _remarks,
    updated_at = _now
  WHERE renewal_id = p_renewal_id;

  IF _owner_id IS NOT NULL AND public.get_system_setting_bool('workflow.notify_org_on_rejected', true) THEN
    INSERT INTO public.notifications (
      user_id,
      organization_id,
      title,
      message,
      type,
      related_type,
      related_id
    ) VALUES (
      _owner_id,
      _renewal.organization_id,
      'Renewal Application Rejected',
      format('Renewal application for Cycle %s was rejected: %s. Please contact the LYDO office directly.', _renewal.cycle_number, _remarks),
      'rejected',
      'renewal',
      p_renewal_id
    );
  END IF;

  INSERT INTO public.activity_logs (
    actor_user_id,
    organization_id,
    action,
    related_type,
    related_id,
    description
  ) VALUES (
    _admin_id,
    _renewal.organization_id,
    'renewal_rejected',
    'renewal',
    p_renewal_id,
    format('Admin rejected renewal application for Cycle %s: %s', _renewal.cycle_number, _remarks)
  );

  RETURN jsonb_build_object(
    'success', true,
    'renewal_id', p_renewal_id,
    'status', 'rejected'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_reject_renewal_in_supabase(p_session_token text, p_renewal_id uuid, p_admin_remarks text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _admin_id uuid;
  _admin_email text;
  _renewal public.organization_renewals%rowtype;
  _submission public.document_submissions%rowtype;
  _owner_id uuid;
  _now timestamptz := clock_timestamp();
  _remarks text;
BEGIN
  -- Authenticate admin session
  SELECT vat.admin_id, vat.email
  INTO _admin_id, _admin_email
  FROM public.validate_admin_session_token(p_session_token) vat
  LIMIT 1;

  IF _admin_id IS NULL THEN
    RAISE EXCEPTION 'Admin session is invalid or expired.';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.admin_users au
    WHERE au.id = _admin_id
      AND au.is_active = true
      AND (au.role_code = 'super_admin' OR 'renewals_manage' = ANY(au.permission_codes))
  ) THEN
    RAISE EXCEPTION 'You do not have permission to reject renewal applications.';
  END IF;

  _remarks := trim(coalesce(p_admin_remarks, ''));
  IF _remarks = '' THEN
    RAISE EXCEPTION 'Remarks documenting the rejection rationale are mandatory.';
  END IF;

  SELECT * INTO _renewal
  FROM public.organization_renewals
  WHERE id = p_renewal_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Renewal record not found: %', p_renewal_id;
  END IF;

  IF _renewal.status NOT IN ('submitted', 'under_review', 'needs_revision') THEN
    RAISE EXCEPTION 'Renewal is not in a rejectable status: %', _renewal.status;
  END IF;

  SELECT * INTO _submission
  FROM public.document_submissions
  WHERE renewal_id = p_renewal_id
  ORDER BY created_at DESC
  LIMIT 1;

  UPDATE public.organization_renewals
  SET
    status = 'rejected',
    reviewed_at = _now,
    reviewed_by = _admin_id,
    admin_remarks = _remarks,
    updated_at = _now
  WHERE id = p_renewal_id;

  IF _submission.id IS NOT NULL THEN
    UPDATE public.document_submissions
    SET
      status = 'rejected',
      reviewed_at = _now,
      reviewed_by = _admin_id,
      admin_remarks = _remarks,
      updated_at = _now
    WHERE id = _submission.id;
  END IF;

  UPDATE public.organization_profiles
  SET
    profile_status = 'suspended_inactive',
    updated_at = _now
  WHERE id = _renewal.organization_id;

  SELECT user_id INTO _owner_id
  FROM public.organization_profiles
  WHERE id = _renewal.organization_id;

  -- Gated organization notification based on workflow.notify_org_on_rejected
  IF _owner_id IS NOT NULL AND public.get_system_setting_bool('workflow.notify_org_on_rejected', true) THEN
    INSERT INTO public.notifications (
      user_id,
      organization_id,
      title,
      message,
      type,
      related_type,
      related_id
    ) VALUES (
      _owner_id,
      _renewal.organization_id,
      'Renewal Rejected',
      format('Your organization renewal for Cycle %s was rejected: %s', _renewal.cycle_number, _remarks),
      'renewal_rejected',
      'renewal',
      p_renewal_id::text
    );
  END IF;

  -- Activity logging remains unconditional
  INSERT INTO public.activity_logs (
    organization_id,
    actor_user_id,
    action,
    related_type,
    related_id,
    description,
    created_at
  ) VALUES (
    _renewal.organization_id,
    _admin_id,
    'renewal_rejected',
    'renewal',
    p_renewal_id::text,
    format('Rejected renewal application for Cycle %s by admin %s. Remarks: %s', _renewal.cycle_number, _admin_email, _remarks),
    _now
  );

  RETURN jsonb_build_object(
    'success', true,
    'renewal_id', p_renewal_id,
    'status', 'rejected'
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.delete_organization_account_canonical(_session_token text, _organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  _admin_id uuid;
  _org public.organization_profiles%rowtype;
  _user_id uuid;
begin
  -- 1. Authorize admin caller
  select vat.admin_id into _admin_id
  from public.validate_admin_session_token(_session_token) vat
  limit 1;

  if _admin_id is null then
    return jsonb_build_object(
      'success', false,
      'stage', 'authorization',
      'error', 'You are not authorized to delete organization accounts.'
    );
  end if;

  -- 2. Lock and load target organization profile
  select * into _org
  from public.organization_profiles
  where id = _organization_id
  for update;

  if not found then
    return jsonb_build_object(
      'success', false,
      'already_deleted', true,
      'stage', 'validation',
      'error', 'Organization profile not found or already deleted.'
    );
  end if;

  _user_id := _org.user_id;

  -- 3. Protection checks: verify target is not an administrator or super admin
  if exists (
    select 1 from public.admin_accounts where lower(trim(email)) = lower(trim(_org.organization_email))
  ) or (_user_id is not null and exists (
    select 1 from public.admin_accounts where id = _user_id
  )) or (_user_id is not null and exists (
    select 1 from public.user_roles ur
    join public.roles r on r.id = ur.role_id
    where ur.user_id = _user_id and r.code::text in ('admin', 'super_admin')
  )) then
    return jsonb_build_object(
      'success', false,
      'is_protected', true,
      'stage', 'protection_check',
      'error', 'Administrator accounts cannot be deleted from the YORP Registry.'
    );
  end if;

  perform ytrace_identity.authorize_reviewer(_session_token);
  if ytrace_identity.has_retained_history(_organization_id) then
    raise exception 'Official organization history is retained. Request an authorized archival/retention review before permanent deletion.';
  end if;

  -- 4. Activate transaction-local bypass for immutability triggers
  perform set_config('app.allow_org_deletion', 'true', true);

  -- 5. Disassociate and clean direct Auth dependencies
  if _user_id is not null then
    -- Nullify submitted_by on YPOP to preserve organization historical context without blocking FK
    update public.ypop_entries
    set submitted_by = null
    where submitted_by = _user_id;

    update public.ypop_event_participations
    set submitted_by = null
    where submitted_by = _user_id;

    update public.ypop_org_activities
    set submitted_by = null
    where submitted_by = _user_id;

    -- Clean user specific auxiliary records
    delete from public.user_policy_acceptance where user_id = _user_id;
    delete from public.user_roles where user_id = _user_id;
    delete from public.user_profiles where user_id = _user_id;
  end if;

  -- 6. Clean accreditation and renewal hierarchies safely
  update public.organization_renewals
  set current_accreditation_id = null
  where organization_id = _organization_id;

  delete from public.organization_renewals
  where organization_id = _organization_id;

  delete from public.organization_accreditations
  where organization_id = _organization_id;

  -- 7. Clean document submissions, budget requests, and liquidations
  delete from public.document_submission_files
  where submission_id in (select id from public.document_submissions where organization_id = _organization_id);

  delete from public.document_submissions
  where organization_id = _organization_id;

  delete from public.budget_request_files
  where budget_request_id in (select id from public.budget_requests where organization_id = _organization_id);

  delete from public.budget_requests
  where organization_id = _organization_id;

  delete from public.liquidation_report_files
  where liquidation_report_id in (select id from public.liquidation_reports where organization_id = _organization_id);

  delete from public.liquidation_reports
  where organization_id = _organization_id;

  -- 8. Clean move applications, URN history, and YPOP organization activities
  delete from public.move_files where organization_id = _organization_id;
  delete from public.move_applications where organization_id = _organization_id;
  delete from public.urn_review_history where organization_id = _organization_id;

  delete from public.ypop_files where organization_id = _organization_id;
  delete from public.ypop_event_files where organization_id = _organization_id;
  delete from public.ypop_org_activity_files where organization_id = _organization_id;
  delete from public.ypop_org_activities where organization_id = _organization_id;
  delete from public.ypop_event_participations where organization_id = _organization_id;
  delete from public.ypop_entries where organization_id = _organization_id;

  -- 9. Clean notifications, compliance remarks, inquiries
  delete from public.notifications where organization_id = _organization_id;
  delete from public.compliance_remarks where organization_id = _organization_id;
  delete from public.inquiries where organization_id = _organization_id;

  -- 10. Disassociate historical activity logs without deleting audit trail
  update public.activity_logs
  set organization_id = null
  where organization_id = _organization_id;

  -- 11. Delete organization profile
  delete from public.organization_profiles
  where id = _organization_id;

  -- 12. Verify organization profile is removed
  if exists (select 1 from public.organization_profiles where id = _organization_id) then
    raise exception 'Database deletion failed: organization_profiles row could not be removed.';
  end if;

  return jsonb_build_object(
    'success', true,
    'organization_id', _org.id,
    'organization_name', _org.organization_name,
    'organization_email', _org.organization_email,
    'user_id', _user_id,
    'urn', _org.urn
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.user_replace_document_submission_file(_file_id uuid, _new_file_url text, _new_file_name text, _new_file_type text, _new_file_size numeric DEFAULT NULL::numeric, _submit_for_review boolean DEFAULT true)
 RETURNS document_submission_files
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _old_file record;
  _submission record;
  _owner_id uuid;
  _history jsonb;
  _history_entry jsonb;
  _updated_row public.document_submission_files;
BEGIN
  SELECT * INTO _old_file
  FROM public.document_submission_files
  WHERE id = _file_id;

  IF _old_file.id IS NULL THEN
    RAISE EXCEPTION 'Document file not found.';
  END IF;

  SELECT * INTO _submission
  FROM public.document_submissions
  WHERE id = _old_file.submission_id;

  IF _submission.id IS NULL THEN
    RAISE EXCEPTION 'Parent document submission not found.';
  END IF;

  SELECT user_id INTO _owner_id
  FROM public.organization_profiles
  WHERE id = _submission.organization_id;

  IF _owner_id <> auth.uid() THEN
    RAISE EXCEPTION 'Unauthorized: Caller does not own this submission.';
  END IF;

  _history_entry := jsonb_build_object(
    'action', 'replaced',
    'previousFileName', _old_file.file_name,
    'previousFileUrl', _old_file.file_url,
    'previousFileType', _old_file.file_type,
    'previousFileSize', _old_file.file_size,
    'previousStatus', _old_file.admin_status,
    'adminRemarks', _old_file.admin_remarks,
    'reviewedAt', _old_file.reviewed_at,
    'replacedAt', clock_timestamp()
  );

  _history := coalesce(_old_file.revision_history, '[]'::jsonb) || jsonb_build_array(_history_entry);

  UPDATE public.document_submission_files
  SET
    file_url = _new_file_url,
    file_name = _new_file_name,
    file_type = _new_file_type,
    file_size = coalesce(_new_file_size, _old_file.file_size),
    admin_status = CASE
      WHEN _submit_for_review THEN 'submitted'::public.document_submission_status
      ELSE 'draft'::public.document_submission_status
    END,
    admin_remarks = NULL,
    reviewed_at = NULL,
    uploaded_at = clock_timestamp(),
    updated_at = clock_timestamp(),
    revision_history = _history
  WHERE id = _file_id
  RETURNING * INTO _updated_row;

  RETURN _updated_row;
END;
$function$

CREATE OR REPLACE FUNCTION public.user_resubmit_renewal(p_renewal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _renewal record;
  _submission record;
  _owner_id uuid;
  _end_date date;
  _now timestamptz := clock_timestamp();
BEGIN
  SELECT * INTO _renewal
  FROM public.organization_renewals
  WHERE id = p_renewal_id
  FOR UPDATE;

  IF _renewal.id IS NULL THEN
    RAISE EXCEPTION 'Renewal application not found.';
  END IF;

  SELECT op.user_id INTO _owner_id
  FROM public.organization_profiles op
  WHERE op.id = _renewal.organization_id;

  IF _owner_id <> auth.uid() THEN
    RAISE EXCEPTION 'Unauthorized: Caller does not own this organization.';
  END IF;

  IF _renewal.status <> 'needs_revision' THEN
    RAISE EXCEPTION 'Renewal cannot be resubmitted from status "%". Expected "needs_revision".', _renewal.status;
  END IF;

  -- Verify within 180-day window
  SELECT oa.end_date INTO _end_date
  FROM public.organization_accreditations oa
  WHERE oa.id = _renewal.current_accreditation_id;

  IF current_date > (_end_date + 180) THEN
    RAISE EXCEPTION 'Late renewal cutoff has passed (180 days past expiration). Resubmission is no longer allowed.';
  END IF;

  -- Verify all flagged documents have been replaced
  SELECT * INTO _submission
  FROM public.document_submissions
  WHERE renewal_id = p_renewal_id
  FOR UPDATE;

  IF _submission.id IS NULL THEN
    RAISE EXCEPTION 'No document submission packet found for this renewal.';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM public.document_submission_files dsf
    WHERE dsf.submission_id = _submission.id
      AND dsf.admin_status IN ('needs_revision', 'rejected_red')
  ) THEN
    RAISE EXCEPTION 'All documents marked for revision or rejection must be replaced before resubmission.';
  END IF;

  -- Update renewal state to resubmitted
  UPDATE public.organization_renewals
  SET
    status = 'resubmitted',
    updated_at = _now
  WHERE id = p_renewal_id;

  -- Update document submission state
  UPDATE public.document_submissions
  SET
    status = 'submitted',
    updated_at = _now
  WHERE id = _submission.id;

  -- Insert activity log with NULL actor_user_id (org user action)
  INSERT INTO public.activity_logs (
    actor_user_id,
    organization_id,
    action,
    related_type,
    related_id,
    description
  ) VALUES (
    NULL,
    _renewal.organization_id,
    'renewal_resubmitted',
    'renewal',
    p_renewal_id,
    format('Organization resubmitted renewal application for Cycle %s after revisions.', _renewal.cycle_number)
  );

  RETURN jsonb_build_object(
    'success', true,
    'renewal_id', p_renewal_id,
    'resubmitted_at', _now
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.user_start_or_get_renewal_draft(p_organization_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _caller_id uuid;
  _profile record;
  _curr_acc record;
  _existing_renewal record;
  _submission record;
  _today date := current_date;
  _end_date date;
  _target_cycle integer;
  _new_renewal record;
  _new_submission record;
BEGIN
  _caller_id := auth.uid();
  IF _caller_id IS NULL THEN
    RAISE EXCEPTION 'Unauthorized: Authentication required.';
  END IF;

  -- Lock organization profile to serialize draft creation
  SELECT op.id, op.user_id, op.profile_status, op.current_accreditation_id, op.accreditation_expires_at
  INTO _profile
  FROM public.organization_profiles op
  WHERE op.id = p_organization_id
  FOR UPDATE;

  IF _profile.id IS NULL THEN
    RAISE EXCEPTION 'Organization profile not found.';
  END IF;

  IF _profile.user_id <> _caller_id THEN
    RAISE EXCEPTION 'Unauthorized: Caller does not own this organization.';
  END IF;

  IF _profile.profile_status <> 'verified' THEN
    RAISE EXCEPTION 'Organization must have verified profile status to initiate renewal.';
  END IF;

  -- Resolve authoritative accreditation term
  SELECT oa.*
  INTO _curr_acc
  FROM public.organization_accreditations oa
  WHERE oa.id = _profile.current_accreditation_id
    AND oa.organization_id = p_organization_id
  LIMIT 1;

  IF _curr_acc.id IS NULL THEN
    SELECT oa.*
    INTO _curr_acc
    FROM public.organization_accreditations oa
    WHERE oa.organization_id = p_organization_id
      AND oa.status = 'active'
    ORDER BY oa.term_number DESC
    LIMIT 1;
  END IF;

  IF _curr_acc.id IS NULL THEN
    RAISE EXCEPTION 'No authoritative accreditation term found for this organization.';
  END IF;

  IF _curr_acc.status = 'revoked' THEN
    RAISE EXCEPTION 'Accreditation has been revoked. Organization cannot renew and must contact LYDO.';
  END IF;

  _end_date := _curr_acc.end_date;

  -- Verify renewal window: [end_date - 90 days, end_date + 180 days]
  IF _today < (_end_date - 90) THEN
    RAISE EXCEPTION 'Renewal window is not yet open. Renewals open 90 days prior to expiration (on %).', (_end_date - 90);
  END IF;

  IF _today > (_end_date + 180) THEN
    RAISE EXCEPTION 'Late renewal window has expired (180 days past expiration). Full re-registration is required.';
  END IF;

  -- Check if a non-terminal renewal is already in progress
  SELECT *
  INTO _existing_renewal
  FROM public.organization_renewals
  WHERE organization_id = p_organization_id
    AND status IN ('draft', 'submitted', 'under_review', 'needs_revision', 'resubmitted')
  ORDER BY cycle_number DESC
  LIMIT 1;

  IF _existing_renewal.id IS NOT NULL THEN
    SELECT * INTO _submission
    FROM public.document_submissions
    WHERE renewal_id = _existing_renewal.id
    LIMIT 1;

    RETURN jsonb_build_object(
      'renewal', row_to_json(_existing_renewal),
      'submission', row_to_json(_submission),
      'is_existing', true
    );
  END IF;

  -- Calculate target cycle number (strictly current_term.term_number + 1)
  _target_cycle := _curr_acc.term_number + 1;

  -- Verify no terminal rejected renewal exists for this cycle
  IF EXISTS (
    SELECT 1 FROM public.organization_renewals
    WHERE organization_id = p_organization_id
      AND cycle_number = _target_cycle
      AND status = 'rejected'
  ) THEN
    RAISE EXCEPTION 'Renewal application for Cycle % was rejected. Organization must contact LYDO directly.', _target_cycle;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.organization_renewals
    WHERE organization_id = p_organization_id
      AND cycle_number = _target_cycle
      AND status = 'approved'
  ) THEN
    RAISE EXCEPTION 'Cycle % is already approved.', _target_cycle;
  END IF;

  -- Create single draft renewal application
  INSERT INTO public.organization_renewals (
    organization_id,
    cycle_number,
    current_accreditation_id,
    status
  ) VALUES (
    p_organization_id,
    _target_cycle,
    _curr_acc.id,
    'draft'
  ) RETURNING * INTO _new_renewal;

  -- Create single linked document submission packet
  INSERT INTO public.document_submissions (
    organization_id,
    submitted_by,
    status,
    user_confirmed,
    submission_scope,
    renewal_id
  ) VALUES (
    p_organization_id,
    _caller_id,
    'draft',
    false,
    'renewal',
    _new_renewal.id
  ) RETURNING * INTO _new_submission;

  RETURN jsonb_build_object(
    'renewal', row_to_json(_new_renewal),
    'submission', row_to_json(_new_submission),
    'is_existing', false
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.user_submit_additional_renewal_documents(p_renewal_id uuid, p_file_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _renewal record;
  _submission record;
  _owner_id uuid;
  _now timestamptz := clock_timestamp();
  _updated_count integer;
  _requested_count integer;
BEGIN
  _requested_count := coalesce(cardinality(p_file_ids), 0);
  IF _requested_count = 0 THEN
    RAISE EXCEPTION 'Select at least one renewal document to submit.';
  END IF;

  IF (SELECT count(DISTINCT requested.file_id) FROM unnest(p_file_ids) AS requested(file_id)) <> _requested_count THEN
    RAISE EXCEPTION 'A renewal document was selected more than once.';
  END IF;

  SELECT * INTO _renewal
  FROM public.organization_renewals
  WHERE id = p_renewal_id
  FOR UPDATE;

  IF _renewal.id IS NULL THEN
    RAISE EXCEPTION 'Renewal application not found.';
  END IF;

  SELECT op.user_id INTO _owner_id
  FROM public.organization_profiles op
  WHERE op.id = _renewal.organization_id;

  IF _owner_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Unauthorized: Caller does not own this organization.';
  END IF;

  IF _renewal.status NOT IN ('submitted', 'under_review', 'resubmitted') THEN
    RAISE EXCEPTION 'Additional documents cannot be submitted from renewal status "%".', _renewal.status;
  END IF;

  SELECT * INTO _submission
  FROM public.document_submissions
  WHERE renewal_id = p_renewal_id
  FOR UPDATE;

  IF _submission.id IS NULL THEN
    RAISE EXCEPTION 'No renewal document submission found.';
  END IF;

  IF EXISTS (
    SELECT 1
    FROM unnest(p_file_ids) AS requested(file_id)
    LEFT JOIN public.document_submission_files dsf
      ON dsf.id = requested.file_id
     AND dsf.submission_id = _submission.id
    LEFT JOIN public.required_document_types rdt
      ON rdt.id = dsf.document_type_id
    WHERE dsf.id IS NULL
      OR dsf.admin_status <> 'draft'
      OR nullif(trim(dsf.file_url), '') IS NULL
      OR rdt.id IS NULL
      OR rdt.is_active IS DISTINCT FROM true
      OR coalesce(rdt.is_required, true) IS DISTINCT FROM true
      OR rdt.scope NOT IN ('renewal', 'both')
      OR rdt.template_scope <> 'document_submission'
  ) THEN
    RAISE EXCEPTION 'Only saved draft files for required renewal documents can be submitted.';
  END IF;

  UPDATE public.document_submission_files
  SET admin_status = 'under_admin_review', reviewed_at = NULL, updated_at = _now
  WHERE submission_id = _submission.id
    AND id = ANY(p_file_ids)
    AND admin_status = 'draft';
  GET DIAGNOSTICS _updated_count = ROW_COUNT;

  IF _updated_count <> _requested_count THEN
    RAISE EXCEPTION 'Not all selected renewal documents could be sent for review.';
  END IF;

  UPDATE public.document_submissions
  SET updated_at = _now
  WHERE id = _submission.id;

  UPDATE public.organization_renewals
  SET updated_at = _now
  WHERE id = p_renewal_id;

  INSERT INTO public.activity_logs (
    actor_user_id, organization_id, action, related_type, related_id, description
  ) VALUES (
    NULL,
    _renewal.organization_id,
    'renewal_documents_submitted',
    'renewal',
    p_renewal_id,
    format('Organization submitted %s additional renewal document(s) for Cycle %s.', _updated_count, _renewal.cycle_number)
  );

  RETURN jsonb_build_object(
    'success', true,
    'renewal_id', p_renewal_id,
    'submitted_count', _updated_count,
    'submitted_at', _now
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.user_submit_renewal(p_renewal_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _renewal record;
  _submission record;
  _owner_id uuid;
  _end_date date;
  _now timestamptz := clock_timestamp();
BEGIN
  SELECT * INTO _renewal
  FROM public.organization_renewals
  WHERE id = p_renewal_id
  FOR UPDATE;

  IF _renewal.id IS NULL THEN
    RAISE EXCEPTION 'Renewal application not found.';
  END IF;

  SELECT op.user_id INTO _owner_id
  FROM public.organization_profiles op
  WHERE op.id = _renewal.organization_id;

  IF _owner_id IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Unauthorized: Caller does not own this organization.';
  END IF;

  IF _renewal.status <> 'draft' THEN
    RAISE EXCEPTION 'Renewal cannot be submitted from status "%". Expected "draft".', _renewal.status;
  END IF;

  SELECT oa.end_date INTO _end_date
  FROM public.organization_accreditations oa
  WHERE oa.id = _renewal.current_accreditation_id;

  IF current_date > (_end_date + 180) THEN
    RAISE EXCEPTION 'Late renewal cutoff has passed (180 days past expiration). Application can no longer be submitted.';
  END IF;

  SELECT * INTO _submission
  FROM public.document_submissions
  WHERE renewal_id = p_renewal_id
  FOR UPDATE;

  IF _submission.id IS NULL THEN
    RAISE EXCEPTION 'No renewal document submission found.';
  END IF;

  -- Each selected document may be sent as it is ready. The admin approval RPC
  -- continues to enforce completeness and approval of every required type.
  IF NOT EXISTS (
    SELECT 1
    FROM public.document_submission_files dsf
    JOIN public.required_document_types rdt ON rdt.id = dsf.document_type_id
    WHERE dsf.submission_id = _submission.id
      AND rdt.is_active = true
      AND coalesce(rdt.is_required, true) = true
      AND rdt.scope IN ('renewal', 'both')
      AND rdt.template_scope = 'document_submission'
      AND nullif(trim(dsf.file_url), '') IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'Upload at least one required renewal document before submitting.';
  END IF;

  UPDATE public.organization_renewals
  SET status = 'submitted', submitted_at = _now, updated_at = _now
  WHERE id = p_renewal_id;

  UPDATE public.document_submissions
  SET status = 'submitted', submitted_at = _now, updated_at = _now
  WHERE id = _submission.id;

  INSERT INTO public.activity_logs (
    actor_user_id, organization_id, action, related_type, related_id, description
  ) VALUES (
    NULL,
    _renewal.organization_id,
    'renewal_submitted',
    'renewal',
    p_renewal_id,
    format('Organization submitted renewal documents for Cycle %s.', _renewal.cycle_number)
  );

  RETURN jsonb_build_object(
    'success', true,
    'renewal_id', p_renewal_id,
    'submitted_at', _now
  );
END;
$function$
